import{_ as t,c as a,o as i,ai as r}from"./chunks/framework.B63Sb1io.js";const l="/img/png/408_CN/24.png",p="/img/png/408_CN/25.png",s="/img/png/408_CN/26.png",n="/img/png/408_CN/27.png",o="/img/png/408_CN/28.png",g=JSON.parse('{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/02/408_CN_17.md","filePath":"post/kaoyan/408/408_CN/02/408_CN_17.md","lastUpdated":1756619081000}'),d={name:"post/kaoyan/408/408_CN/02/408_CN_17.md"};function m(c,e,_,h,u,x){return i(),a("div",null,e[0]||(e[0]=[r('<h1 id="双绞线、同轴电缆、光纤与无线传输介质" tabindex="-1">双绞线、同轴电缆、光纤与无线传输介质 <a class="header-anchor" href="#双绞线、同轴电缆、光纤与无线传输介质" aria-label="Permalink to &quot;双绞线、同轴电缆、光纤与无线传输介质&quot;">​</a></h1><br><p>传输介质也称传输媒体，是数据传输系统中发送器和接收器之间的物理通路。传输介质可分为：</p><p>（1）导向传输介质，指铜线或光纤等，电磁波被导向为沿固体介质传播；</p><p>（2）非导向传输介质，指自由空间（空气、真空或海水），电磁波在非导向传输介质中的传输称为无线传输。</p><h2 id="双绞线" tabindex="-1">双绞线 <a class="header-anchor" href="#双绞线" aria-label="Permalink to &quot;双绞线&quot;">​</a></h2><p>双绞线是最常用的传输介质，在局域网和传统电话网中普遍使用。双绞线由两根采用一定规则并排绞合、相互绝缘的铜导线组成。绞合可减少对相邻导线的电磁干扰。为了进一步提高抗电磁干扰的能力，还可在双绞线的外面加上一层金属丝编织成的屏蔽层，这就是屏蔽双绞线（STP）。无屏蔽层的双绞线称为非屏蔽双绞线（UTP）。双绞线的结构如图所示。</p><p>双绞线的价格便宜，模拟传输和数字传输都可使用双绞线，通信距离一般为几千米到数十千米。双绞线的带宽取决于铜线的粗细和传输的距离。距离太远时，对于模拟传输，要用放大器放大衰减的信号；对于数字传输，要用中继器来对失真的信号进行整形。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+l+'" alt="单向通信系统模型" width="450px" style="border-radius:10px;"></div><br><h2 id="同轴电缆" tabindex="-1">同轴电缆 <a class="header-anchor" href="#同轴电缆" aria-label="Permalink to &quot;同轴电缆&quot;">​</a></h2><p>同轴电缆由内导体、绝缘层、外导体屏蔽层和绝缘保护套层构成，如图 2.5 所示。同轴电缆一般分为两类：</p><p>（1） $ 50 \\Omega $ 同轴电缆，主要用于传送基带数字信号，在早期局域网中应用广泛；</p><p>（2） $ 75 \\Omega $同轴电缆，主要用于传送宽带信号，在有线电视系统中应用广泛。因为外导体屏蔽层的作用，所以同轴电缆具有良好的抗干扰特性而被广泛用于传输较高速率的数据。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+p+'" alt="同轴电缆" width="350px" style="border-radius:10px;"></div><br><p>随着技术的发展和集线器的出现，在局域网领域基本上都采用双绞线作为传输介质。</p><h2 id="光纤" tabindex="-1">光纤 <a class="header-anchor" href="#光纤" aria-label="Permalink to &quot;光纤&quot;">​</a></h2><p>光纤通信是指利用光导纤维（简称光纤）传递光脉冲来进行通信。有光脉冲表示 1 ，无光脉冲表示 0 。可见光的频率约为 $ 10^{8} \\mathrm{MHz} $ ，因此光纤通信系统的带宽极大。</p><p>光纤主要由纤芯和包层构成（见图2．6），纤芯很细，直径仅为 $ 8 \\sim 100 \\mu \\mathrm{~m} $ ，包层较纤芯有较低的折射率，光波通过纤芯进行传导。当光线从高折射率的介质射向低折射率的介质时，其折射角将大于入射角。因此，只要入射角大于某个临界角，就会出现全反射，即光线碰到包层时就会折射回纤芯，这个过程不断重复，光也就沿着光纤传输下去。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+s+'" alt="光纤" width="450px" style="border-radius:10px;"></div><br><p>利用光的全反射特性，可让从不同角度入射的多条光线在一根光纤中传输，这种光纤称为多模光纤（见图2．7）。光脉冲在多模光纤中传输的损耗更高，因此较适合近距离传输。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+n+'" alt="光纤" width="550px" style="border-radius:10px;"></div><br><p>当光纤的直径减小到只有一个光的波长时，光纤就像一根波导那样，可使光线一直向前传播，而不产生多次反射，这样的光纤就是单模光纤（见图2．8）。单模光纤的纤芯很细，直径只有几微米，制造成本较高。同时，单模光纤的光源是定向性很好的半导体激光器，因此单模光纤的衰减较小，可传输数千米甚至数十千米而不必采用中继器，适合远距离传输。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+o+'" alt="光纤" width="550px" style="border-radius:10px;"></div><br><p>光纤不仅具有通信容量非常大的优点，还具有如下特点：</p><ul><li>传输损耗小，中继距离长，对远距离传输特别经济。</li><li>抗雷电和电磁干扰性能好，在有大电流脉冲干扰的环境下这尤为重要。</li><li>无串音干扰，保密性好，不易被窃听或截取数据。</li><li>体积小，重量轻，在现有电缆管道已拥塞不堪的情况下这特别有利。</li></ul><h2 id="无线传输介质" tabindex="-1">无线传输介质 <a class="header-anchor" href="#无线传输介质" aria-label="Permalink to &quot;无线传输介质&quot;">​</a></h2><p>无线通信已广泛用于蜂窝移动电话领域。便携式计算机的出现，以及军事、野外等特殊场合对移动联网的需要，促进了移动通信的发展，现在无线局域网的应用已非常普遍。</p><p>（1）无线电波 无线电波具有较强的穿透能力，可以传输很长的距离，因此广泛用于通信领域，如无线手机通信、计算机网络中的无线局域网（WLAN）等。因为无线电波使信号向所有方向散播，所以有效距离范围内的接收设备无须对准某个方向，就可与无线电波发射者进行通信连接，大大简化了通信连接。这也是无线电波传输的最重要优点之一。 （2）微波、红外线和激光 目前高带宽的无线通信主要使用三种技术：微波、红外线和激光，它们都需要在发送方和接收方之间有一条视线通路，有很强的指向性。不同的是，红外线通信和激光通信将要传输的信号分别转换为各自的信号格式，即红外线信号和激光信号，再直接在空间中传播。</p><p>微波通信的频率较高，频段范围也很宽，载波频率通常为 $ 2 \\sim 40 \\mathrm{GHz} $ ，因此通信信道的容量大。例如，一个带宽为 2 MHz 的频段可容纳 500 条语音线路，若用来传输数字信号，则数据率可达数兆比特／秒。与通常的无线电波不同，微波通信的信号是沿直线传播的，因此在地面上的传播距离有限，超过一定距离后就要使用中继站来接力。</p><p>卫星通信利用地球同步卫星作为中继站来转发微波信号，可以突破地面微波通信距离的限制。三颗相隔 $ 120^{\\circ} $ 的同步卫星几乎就能覆盖整个地球表面，因此基本能实现全球通信。卫星通信的优点是通信容量大、距离远、覆盖广，缺点是保密性差、端到端传播时延长。</p>',40)]))}const f=t(d,[["render",m]]);export{g as __pageData,f as default};
